-- Kana crossword: a learner's finished puzzles. Puzzles themselves are
-- generated and never stored; this keeps that a learner finished one, its
-- times, and the words it used (so the next puzzle can avoid repeating them).
--
-- Generated by drizzle-kit, then made idempotent by hand. Purely additive — one
-- new table, nothing existing is touched.

CREATE TABLE IF NOT EXISTS "crossword_results" (
	"user_id" text NOT NULL,
	"puzzle_key" text NOT NULL,
	"language_id" text NOT NULL,
	"level_id" text NOT NULL,
	"source" text NOT NULL,
	"word_ids" text[] DEFAULT '{}' NOT NULL,
	"best_seconds" integer NOT NULL,
	"last_seconds" integer NOT NULL,
	"hints_used" integer DEFAULT 0 NOT NULL,
	"completed_at" timestamp DEFAULT now() NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "crossword_results_user_id_puzzle_key_pk" PRIMARY KEY("user_id","puzzle_key"),
	CONSTRAINT "crossword_results_sensible_times" CHECK ("crossword_results"."best_seconds" >= 0 and "crossword_results"."last_seconds" >= 0 and "crossword_results"."hints_used" >= 0)
);
--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "crossword_results" ADD CONSTRAINT "crossword_results_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "crossword_results" ADD CONSTRAINT "crossword_results_language_id_languages_id_fk" FOREIGN KEY ("language_id") REFERENCES "public"."languages"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "crossword_results" ADD CONSTRAINT "crossword_results_level_id_language_levels_id_fk" FOREIGN KEY ("level_id") REFERENCES "public"."language_levels"("id") ON DELETE restrict ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "crossword_results_recent_idx" ON "crossword_results" USING btree ("user_id","completed_at");
